import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>لديك صورة بألوان تعشقها، وتحتاج تلك الألوان كلوحة لموقع أو ملصق أو علامة. نسخها بالعين بطيء وغير دقيق.</p>\n<p>هذا الدليل يأخذك خطوة بخطوة لاستخراج لوحة ألوان من صورة في خمس خطوات: رفع واختيار عدد العينات وقراءة النسب ونسخ النتيجة أو تنزيلها.</p>\n<p>العملية كلها تستغرق أقل من دقيقة بمجرد أن تعرفها. لا برنامج للتثبيت ولا حساب للإنشاء ولا ملف يُرفع إلى أي خادم.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج الصورة التي تحمل الألوان، بصيغة JPG أو PNG أو WebP، حتى 20 MB: صورة فوتوغرافية أو صورة منتج أو لقطة شاشة أو عمل فني تعمل.</p>\n<p>اعرف ما الغرض من اللوحة: سمة موقع تحتاج أربعة إلى ستة ألوان، وهوية علامة تحتاج بضعة ألوان أكثر، ولوحة إلهام تستطيع استخدام الاثني عشر كاملة. والمتصفح هو كل البرامج التي تحتاجها: تعمل الأداة في Chrome وSafari وFirefox وEdge، على الحاسوب والهاتف، دون أي إضافة.</p>\n<p>وأخيرًا، استخدم أنظف ملف أصلي لديك: نسخة معاد ضغطها أو لقطة للصورة قد تغيّر قيم البكسل قليلًا وتغيّر اللوحة الناتجة.</p>\n<h2 id=\"step-1-upload-or-paste\">الخطوة 1: ارفع الصورة أو الصق لقطة شاشة</h2>\n<p>افتح <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصورة</a> واسحب صورتك إلى منطقة الرفع. ويمكنك أيضًا النقر على المنطقة لاختيار ملف من جهازك.</p>\n<p>وإذا كانت الألوان على شاشتك الآن، التقط لقطة شاشة والصقها بـCtrl+V: تقبل الأداة صور الحافظة مباشرة، فتستطيع استخراج لوحة من أي شيء تراه. وتظهر اللوحة فور تحميل الصورة، بدءًا بالقيمة الافتراضية 6 عينات: كل عينة تُظهر لونها ورموزها والنسبة المئوية للصورة التي تغطيها.</p>\n<p>وإذا رفعت الملف الخطأ، بدّل إلى صورة أخرى من الأداة: تُستبدل اللوحة القديمة، وتستطيع متابعة العمل دون إعادة تحميل الصفحة.</p>\n<h2 id=\"step-2-choose-swatch-count\">الخطوة 2: اختر كم عينة تريد</h2>\n<p>حرّك المنزلق لتثبيت عدد العينات بين 3 و12: تُعاد بناء اللوحة فورًا في كل مرة تحركه، فتستطيع مقارنة الأعداد في ثوانٍ.</p>\n<p>ابدأ بـ6 وراقب النتيجة: إذا بدت عينتان شبه متطابقتين، اخفض العدد إلى 4 أو 5 وراقب كيف تندمج المكررات في لون أنظف. وإذا فقد لون تمييز يهمك، ارفع العدد نحو 12: عينات أكثر تمنح التفاصيل الصغيرة صناديقها الخاصة، فيستطيع لافتة نيون صغيرة أو زهرة صغيرة أن تظهر.</p>\n<p>لا عدد صحيح واحد: موقع بسيط يريد 3 أو 4، ولوحة علامة غنية تريد 8 أو 10، والمنزلق موجود لتجد الرقم الذي يناسب مشروعك.</p>\n<h2 id=\"step-3-read-the-percentages\">الخطوة 3: اقرأ النسب والشريط</h2>\n<p>تحمل كل عينة شارة نسبة تُظهر كم من الصورة يغطي ذلك اللون: النسبة الأكبر هي اللون المهيمن، والأصغر هي التمييزات.</p>\n<p>اقرأ النسب كتسلسل هرمي لتصميمك: يجب أن يشغل اللون المهيمن أكبر مساحة، واللون الثانوي دورًا داعمًا، والألوان الأصغر فقط التفاصيل المميزة. وانظر إلى شريط الألوان المتناسب تحت العينات: يُظهر نفس التسلسل كشريط، بعرض مقاطع يطابق النسب، ما يسهل الحكم على التوازن.</p>\n<p>وإذا كان الشريط معظمه لونًا واحدًا، فللصورة نغمة مهيمنة قوية، وسيشعر تصميمك بالهدوء. وإذا كان الشريط مقسومًا بالتساوي، فالصورة مزدحمة، وسيحتاج تصميمك إلى ضبط أكثر.</p>\n<h2 id=\"step-4-copy-css-or-json\">الخطوة 4: انسخ اللوحة كـCSS أو JSON</h2>\n<p>انقر نسخ CSS لنسخ كل العينات كخصائص CSS مخصصة: تُسمى المتغيرات بالترتيب، كل منها بقيمة HEX، وتُلصق مباشرة في ورقة أنماط.</p>\n<p>انقر نسخ JSON عندما تغذي اللوحة كودًا بدل ورقة أنماط: يشمل JSON قيم HEX وRGB وHSL لكل لون إضافة إلى حصته المئوية، بصيغة يستطيع سكربت قراءتها. وغيّر عدد العينات وتتحدث الصادرات: تستطيع الانتقال من 6 ألوان إلى 4 دون إعادة الرفع، ويعكس CSS أو JSON المنسوخ المجموعة الجديدة فورًا.</p>\n<p>احفظ التصدير مع المشروع: لوحة تعيش فقط في تبويب متصفح تختفي عندما يُغلق التبويب، بينما ملف محفوظ موجود عندما يُعاد فتح المشروع.</p>\n<h2 id=\"step-5-download-palette-card\">الخطوة 5: نزّل بطاقة اللوحة</h2>\n<p>انقر تنزيل لوحة PNG لتوليد بطاقة لوحة: الصورة الأصلية مع شريط العينات والألوان موضوعة تحتها. إنها الملخص البصري للاستخراج.</p>\n<p>شارك البطاقة مع عميل أو فريق: صورة للوحة تتواصل أسرع من قائمة رموز HEX، خصوصًا مع أشخاص لا يقرؤون الكود. واستخدم البطاقة في لوحات الإلهام ومستندات العلامة والعروض: تُظهر من أين جاءت الألوان، ما يبني الثقة، لأن العميل يستطيع رؤية الصورة المصدر.</p>\n<p>احفظ البطاقة مع ملفات المشروع: عندما تُساءل اللوحة بعد أشهر، تُظهر البطاقة المصدر والمنطق في صورة واحدة.</p>\n<h2 id=\"extracting-from-a-photo\">كيف تستخرج لوحة من صورة</h2>\n<p>الصور هي أفضل مصدر للوحات، لأن ألوانها تعمل معًا بالفعل في العالم الحقيقي: غروب أو مشهد شارع أو صورة منتج تستطيع إعطاء مخطط كامل.</p>\n<p>ابدأ بأكبر المناطق المسطحة في الصورة: سماء صافية أو جدار مطلي أو قطعة ملابس تعطي لونًا مستقرًا يرتبه المستخرج عاليًا وبموثوقية. وانتبه للإضاءة المختلطة: صورة بضوء شمس دافئ على جانب وظل بارد على الآخر قد تنتج نسختين من نفس اللون، تبدوان كمكررات في اللوحة.</p>\n<p>وعند حدوث ذلك، اختر النسخة التي تطابق المزاج الذي تريده: الدافئة تناسب تصميمًا مريحًا، والباردة تناسب تصميمًا حادًا، والاحتفاظ بالاثنتين غالبًا يعكّر اللوحة.</p>\n<h2 id=\"extracting-from-a-logo\">كيف تستخرج لوحة من شعار</h2>\n<p>الشعارات حالة دقة، لأن لوحة علامة يجب أن تطابق بالضبط: ابدأ بأعلى ملف شعار جودة لديك، ويفضل PNG فوق خلفية صلبة.</p>\n<p>يتعامل المستخرج مع الخلفيات الشفافة، لأنه يتجاهل البكسلات الشفافة تمامًا. لكن شعارًا فوق خلفية شفافة ما زال قد ينتج نتائج غريبة إذا كانت الحواف ناعمة أو مضادة للتعرج. ولأنظف نتيجة، ضع الشعار أولًا فوق خلفية بيضاء أو بلون العلامة واستخرج من تلك النسخة: ستعكس اللوحة حينها ألوان الشعار، لا معالجة الشفافية.</p>\n<p>تحقق بعدها من الألوان الرئيسية بـ<a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a>: يقرأ المنتقي البكسل الدقيق، ما يؤكد لون العلامة عندما تبدو قيمة المستخرج منحرفة قليلًا.</p>\n<h2 id=\"extracting-from-a-screenshot\">كيف تستخرج لوحة من لقطة شاشة</h2>\n<p>لقطات الشاشة هي أسرع طريقة لالتقاط لوحة موقع أو تطبيق تعجب به: التقط الشاشة والصقها بـCtrl+V فتظهر اللوحة.</p>\n<p>يرتب المستخرج ألوان الواجهة حسب التغطية، فتهيمن الخلفية والأسطح الرئيسية، بينما تظهر ألوان الأزرار والروابط كتمييزات صغيرة. وانتبه للنص: لقطة مليئة بالنص تنتج عينات رمادية وسوداء من الحروف، ليست جزءًا من لوحة التصميم ويجب تجاهلها.</p>\n<p>وتذكر مسألة الأصالة: لوحة مستوحاة من موقع آخر جيدة، لكن نسخ لوحة علامة منافسة بالكامل اختيار سيئ لعمل العملاء.</p>\n<h2 id=\"when-an-accent-goes-missing\">عندما يفقد تمييز صغير</h2>\n<p>تمييز صغير قد يختفي من لوحة لأن المستخرج يرتب الألوان حسب التغطية: لافتة نيون تغطي 1 بالمئة من صورة قد تطوى في لون مجاور.</p>\n<p>ارفع عدد العينات نحو 12 أولًا: عينات أكثر تمنح التفاصيل الصغيرة صناديقها الخاصة، فيكون للتمييز فرصة أفضل للظهور. وإذا لم يظهر مع ذلك، التقطه بالقطارة: يقرأ <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a> البكسل الدقيق، وتستطيع إضافة ذلك اللون إلى اللوحة المستخرجة يدويًا.</p>\n<p>دوّن نسبة التمييز عندما تضيفه يدويًا: تمييز 1 بالمئة هو لون مميز، لا لون رئيسي، واستخدامه في مناطق كبيرة سيطغى على التصميم.</p>\n<h2 id=\"fixing-duplicate-shades\">كيف تصلح درجات مكررة في اللوحة</h2>\n<p>عينتان تبدوان شبه متطابقتين غالبًا تأتيان من تدرج، مثل سماء تتغير تدريجيًا من أزرق فاتح إلى أزرق أدكن: يقسم الخوارزم التدرج إلى صندوقين.</p>\n<p>احتفظ بالدرجة التي تناسب تصميمك وتخلص من الأخرى: لوحة بزرق واحد أنظف من لوحة بزرقين لا يستطيع أحد تمييزهما. وكبديل، اخفض عدد العينات: مع 6 ألوان، يقع التدرج غالبًا في صندوق واحد، ويختفي المكرر دون أي تعديل يدوي.</p>\n<p>وعندما تتخلص من مكرر، راجع النسب: يجب أن يحمل اللون المحتفظ به الحصة المدمجة في تصميمك، لأن الدرجتين معًا غطتا تلك الحصة من الصورة.</p>\n<h2 id=\"using-the-palette-in-design-tools\">كيف تستخدم اللوحة في Figma وCanva وCSS</h2>\n<p>في Figma، الصق كل رمز HEX في نمط لون: أنشئ نمطًا لكل عينة، مسمى بدوره، مثل خلفية ورئيسي وتمييز، ليستخدمها الفريق باتساق.</p>\n<p>في Canva، الصق رموز HEX في مجموعة العلامة أو في منتقي لون كل عنصر: تبقى اللوحة حينها متاحة في كل تصاميم الحساب. وفي CSS، الصق الخصائص المخصصة المنسوخة في ورقة أنماطك وأشِر إلى المتغيرات في كل مكان: لوحة قائمة على متغيرات سهلة التحديث، لأن تغيير قيمة واحدة يحدّث كل استخدام.</p>\n<p>ولنظام تصميم، احفظ تصدير JSON كمصدر حقيقة: يستطيع سير رموز قراءته وتوليد CSS ومتغيرات Figma والتوثيق من نفس الملف.</p>\n<h2 id=\"switching-count-without-reupload\">كيف تغيّر العدد دون إعادة رفع</h2>\n<p>تستطيع تغيير عدد العينات في أي وقت دون رفع الصورة مجددًا: حرّك المنزلق وتُعاد بناء اللوحة من نفس بيانات الصورة فورًا.</p>\n<p>هذا مفيد لمقارنة الأعداد: جرّب 4 ثم 6 ثم 8، وراقب كيف تكتسب اللوحة تفاصيل ثم تبدأ في تكرار الدرجات. والعدد الصحيح غالبًا قبل أن تبدأ المكررات في الظهور. وانسخ CSS أو JSON بعد كل تغيير إن أردت الاحتفاظ بنسخ عدة: التصدير يعكس دائمًا العدد الحالي، فنسخة أعجبتك قد تُفقد إذا حرّكت المنزلق.</p>\n<p>رفع صورة جديدة يمسح اللوحة القديمة تلقائيًا: هذا يبقي الأداة مرتبة، لكنه يعني أنك يجب أن تحفظ أي لوحة تريد الاحتفاظ بها قبل تبديل الصور.</p>\n<h2 id=\"extracting-from-product-photos\">كيف تستخرج لوحة من صور منتج</h2>\n<p>صور المنتج حالة خاصة، لأن اللوحة يجب أن تخدم المنتج، لا الصورة فقط: صورة منتج فوق خلفية بيضاء تعطي لوحة يهيمن عليها الأبيض، ما يقول قليلًا عن المنتج.</p>\n<p>لعمل المنتج، استخرج من صورة نمط حياة بدل صورة استوديو: منتج مصور أثناء الاستخدام، في غرفة أو في الهواء الطلق، يحمل ألوان سياقه. وعندما توجد صورة استوديو فقط، قص المنتج بإحكام قبل الاستخراج: إزالة الخلفية البيضاء تجبر المستخرج على ترتيب ألوان المنتج بدل المساحة الفارغة.</p>\n<p>قارن اللوحة بألوان المنتج التي تعرفها: إذا فقد لون علامة المنتج أو تغيّر، تحقق منه بالقطارة وأضفه إلى اللوحة يدويًا. وتغذي لوحات المنتج إعلانات وتغليفًا ودعاية، فالاتساق يهم أكثر من المعتاد: احفظ تصدير CSS أو JSON مع ملفات المنتج، واستخدم نفس اللوحة عبر كل أصول المنتج.</p>\n<p>ولنطاق منتجات، استخرج لوحة من كل منتج وقارنها: المنتجات التي تشترك في عائلة لوحة تبدو كنطاق، بينما المنتجات بلوحات غير مترابطة تبدو عشوائية. وتستحق منتجات الموسم لوحات موسمية: صورة منتج صيفية تعطي ألوانًا ساطعة ودافئة، بينما نسخة الشتاء من نفس المنتج تعطي نغمات أعمق.</p>\n<p>وأخيرًا، اختبر اللوحة في إعلان السوق نفسه: لوحة تبدو جيدة في أداة تصميم قد تفشل مقابل خلفية السوق البيضاء وألوان واجهته، فاختبرها حيث ستعيش.</p>\n<h2 id=\"quick-reference-checklist\">قائمة مرجعية سريعة</h2>\n<p>ارفع أنظف أصل وثبّت عدد العينات واقرأ النسب والشريط، ثم انسخ CSS أو JSON ونزّل بطاقة اللوحة.</p>\n<p>قلّم شبه المكررات وأنقذ التمييزات المفقودة بالقطارة واحفظ التصدير مع المشروع قبل إغلاق التبويب.</p>\n<p>للسياق الكامل، اقرأ <a href=\"/ar/blog/dalil-istikraj-lauhat-alwan-min-as-suwar/\">دليل مستخرج لوحة الألوان الكامل</a>، ولنصائح سير التصميم راجع <a href=\"/ar/blog/lauhat-alwan-min-as-suwar-li-at-tasmim/\">لوحات ألوان من الصور: نصائح سير التصميم</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أختار أي الألوان المستخرجة أستخدم فعلًا؟","answer":"ابدأ باللون الأعلى نسبة كمهيمن، وخذ الثاني الأعلى كثانوي، واستخدم الأصغر كتمييزات. وأربعة إلى ستة ألوان تكفي لمعظم التصاميم. وتخلص من شبه المكررات واحتفظ فقط بالألوان التي تضيف شيئًا."},{"question":"هل يمكنني استخراج لوحة من لقطة فيديو أو إطار فيلم؟","answer":"نعم، التقط لقطة شاشة للإطار والصقها في المستخرج فتظهر اللوحة. ولقطات الأفلام مصادر ممتازة لأن مديري التصوير يصممون مخططاتهم اللونية بعناية، فتمنحك لوحات سينمائية جاهزة."},{"question":"لماذا لا تجمع النسب إلى 100 بالمئة؟","answer":"غالبًا تجمع، ضمن التقريب: كل نسبة عينة تُقرب إلى عدد صحيح، فالقيم المعروضة قد تجمع 99 أو 101 بالمئة. والحصص الكامنة دقيقة، والتقريب فقط هو ما يحرّك المجموع قليلًا."},{"question":"ما الفرق بين بطاقة اللوحة وتصدير CSS؟","answer":"بطاقة اللوحة صورة PNG تُظهر الصورة مع عيناتها، صُنعت للمشاركة مع الناس. وتصدير CSS نص بمتغيرات الألوان، صُنع للصق في كود. واستخدم البطاقة للعملاء وCSS للمطورين."},{"question":"هل يمكنني استخراج لوحة من صورة أبيض وأسود؟","answer":"نعم، لكن النتيجة ستكون درجات رمادية: النسب ما زالت تُظهر البنية النغمية للصورة، وهو مفيد عندما تصمم بأحادي اللون. ولوحة رمادية من صورة قوية قد تكون أساسًا أنيقًا لتصميم."},{"question":"كيف أشارك لوحة مستخرجة مع عميل لا يستخدم أدوات تصميم؟","answer":"نزّل بطاقة اللوحة PNG وأرسلها: تُظهر البطاقة الصورة المصدر مع العينات تحتها، فيستطيع أي شخص رؤية الألوان ومن أين جاءت. وأضف رموز HEX في الرسالة أيضًا، ليستطيع فريق العميل استخدامها."}];
